502:   // ---------- simulation ----------
503:   function levelVal(def, field, level) {
504:     const arr = def[field];
505:     if (Array.isArray(arr)) return arr[Math.min(level, arr.length - 1)] || 0;
506:     return arr || 0;
507:   }
508:   function zoneArtKind(def) {
509:     return def.kind === 'zone-r' ? 'r' : def.kind === 'zone-c' ? 'c' : 'i';
510:   }
511:   function bCenter(b) { return { x: b.x + b.w / 2, y: b.y + b.h / 2 }; }
512:   function distance(a, b) {
513:     const ca = bCenter(a), cb = bCenter(b);
514:     return Math.hypot(ca.x - cb.x, ca.y - cb.y);
515:   }
516:   function nearbyArt(b, arts, radiusOverride) {
517:     for (const o of state.buildings) {
518:       if (o === b) continue;
519:       const d = defOf(o);
520:       if (!d) continue;
521:       const art = KK.render.artFor(d, o.level);
522:       if (!arts.includes(art)) continue;
523:       const r = radiusOverride || d.radius || 0;
524:       if (distance(b, o) <= r) return true;
525:     }
526:     return false;
527:   }
