653:   function simulateTick() {
654:     if (!state) return;
655:     state.tick++;
656:     const scale = periodScale();
657:     state.elapsedDays = (state.elapsedDays || 0) + PERIOD_DAYS[state.period];
658:     state.hour = (state.hour + .24 * scale) % 24;
659:     state.moodBoost *= Math.pow(.966, scale);
660:     if (Math.abs(state.moodBoost) < .05) state.moodBoost = 0;
661:     recalc();
662:     const hasPower = state.powerCap >= state.powerUse;
663:     const hasWater = state.waterCap >= state.waterUse;
664:     let changed = false;
665:     for (const b of state.buildings.slice()) {
666:       const d = defOf(b);
667:       if (!d || !d.kind || !d.kind.startsWith('zone')) continue;
668:       const ok = hasPower && hasWater && roadAccess(b);
669:       if (b.level === 0) {
670:         const kind = zoneArtKind(d);
671:         if (ok && demandFor(kind) > 0 && state.happiness >= 38) {
672:           b.growth += (1 + (state.happiness > 66 ? .5 : 0)) * scale;
673:           if (b.growth >= 2) { b.level = 1; b.growth = 0; b.evo = 0; changed = true; }
674:         } else b.growth = Math.max(0, b.growth - .5 * scale);
675:       } else {
676:         const school = nearbyArt(b, ['school']);
677:         const hospital = nearbyArt(b, ['hospital']);
678:         let maxLv = 3;
679:         if (kindOf(d) === 'r') maxLv = 2 + (school ? 1 : 0) + (hospital ? 1 : 0);
680:         if (b.level < Math.min(d.maxLevel || 3, maxLv) && ok && state.happiness >= 50) {
681:           b.evo += (state.happiness >= 68 ? 2 : 1) * scale;
682:           const need = [0, 7, 13, 21][b.level] || 99;
683:           if (b.evo >= need) { b.level++; b.evo = 0; changed = true; }
684:         } else if (b.evo > 0) b.evo = Math.max(0, b.evo - scale);
685:       }
686:     }
687:     if (changed) recalc();
688:     state.money += (state.income - state.expense) * scale;
689:     // resource warnings
690:     if (!state.warned.power && state.powerUse > state.powerCap && state.powerUse > 0) {
691:       toast('Listrik tidak cukup! Bangun pembangkit atau taman surya.', 'bad', 'bolt');
692:       state.warned.power = true;
693:     }
694:     if (state.powerUse <= state.powerCap) state.warned.power = false;
695:     if (!state.warned.water && state.waterUse > state.waterCap && state.waterUse > 0) {
696:       toast('Pasokan air kurang! Bangun menara air tambahan.', 'bad', 'drop');
697:       state.warned.water = true;
698:     }
699:     if (state.waterUse <= state.waterCap) state.warned.water = false;
700:     checkUnlocks();
701:     checkMissions();
702:     // random city event
703:     state.eventTimer = (state.eventTimer || 48) - scale;
704:     if (state.eventTimer <= 0) {
705:       state.eventTimer = 55 + Math.floor(Math.random() * 25);
706:       if (!state.modalPause && state.population >= 20) setTimeout(showRandomEvent, 350);
707:     }
708:     if (state.tick % Math.max(1, Math.round(2 / scale)) === 0) spawnCars();
709:     if (state.tick % Math.max(1, Math.round(20 / scale)) === 0) saveGame(true);
710:     updateAll();
711:     updateSelection();
712:   }
713:   function kindOf(def) { return def.kind === 'zone-r' ? 'r' : def.kind === 'zone-c' ? 'c' : 'i'; }
714: 
715:   function checkUnlocks(silent) {
716:     if (!state) return;
717:     for (const id in DEFS) {
718:       const d = DEFS[id];
719:       if (!d.unlockPop || d.unlockPop > state.maxPop) continue;
720:       if (!state.unlocked[id]) {
721:         state.unlocked[id] = true;
722:         if (!silent) {
