125:   function drawPlate(ctx, grid) {
126:     const p = isoPts([[0, 0], [grid, 0], [grid, grid], [0, grid]]);
127:     const cx = 0, cy = grid * IY;
128:     const shadow = ctx.createRadialGradient(cx, cy + 40, 40, cx, cy + 40, grid * 42);
129:     shadow.addColorStop(0, 'rgba(3,35,42,.30)');
130:     shadow.addColorStop(.7, 'rgba(3,35,42,.10)');
131:     shadow.addColorStop(1, 'rgba(3,35,42,0)');
132:     ctx.save();
133:     ctx.translate(0, 34);
134:     ctx.scale(1.02, .88);
135:     ctx.fillStyle = shadow;
136:     ctx.beginPath(); ctx.ellipse(cx, cy, grid * 34, grid * 20, 0, 0, Math.PI * 2); ctx.fill();
137:     ctx.restore();
138:     const depth = 20;
139:     // visible cliff sides
140:     poly(ctx, [p[3], p[2], { x: p[2].x, y: p[2].y + depth }, { x: p[3].x, y: p[3].y + depth }], '#4e4032');
141:     poly(ctx, [p[2], p[1], { x: p[1].x, y: p[1].y + depth }, { x: p[2].x, y: p[2].y + depth }], '#64513e');
142:     poly(ctx, [p[3], p[0], { x: p[0].x, y: p[0].y + depth }, { x: p[3].x, y: p[3].y + depth }], '#3f3529');
143:     poly(ctx, [p[0], p[1], { x: p[1].x, y: p[1].y + depth }, { x: p[0].x, y: p[0].y + depth }], '#574636');
144:     poly(ctx, p, '#6ea758');
145:     // outer grass rim
146:     const rim = diamondPoints(0, 0, grid, grid, .1);
147:     poly(ctx, rim, '#78b45e');
148:   }
149: 
150:   // ---------- terrain ----------
151:   const GRASS = ['#8bcb67', '#85c562', '#91d06d', '#7fbe5d', '#96d371'];
152:   const SAND = ['#e7d19a', '#e3ca8e', '#edd8a6'];
153:   function drawTerrain(ctx, world, x, y, tile, time) {
154:     const T = iso(x, y), R = iso(x + 1, y), B = iso(x + 1, y + 1), L = iso(x, y + 1);
155:     const h = hash(x, y);
156:     if (tile.terrain === 'water') {
157:       const base = h > .5 ? '#3d9fc0' : '#429fbe';
158:       poly(ctx, [T, R, B, L], base);
159:       const shimmer = (Math.sin(time * 1.1 + x * 1.7 + y * 2.3) + 1) / 2;
160:       ctx.globalAlpha = .18 + shimmer * .18;
161:       line(ctx, { x: T.x + 16, y: T.y + 10 }, { x: T.x + 25, y: T.y + 14.5 }, '#e9ffff', 1.4);
162:       line(ctx, { x: T.x + 9, y: T.y + 20 }, { x: T.x + 17, y: T.y + 24 }, '#d8fbff', 1.2);
163:       line(ctx, { x: T.x + 27, y: T.y + 21 }, { x: T.x + 35, y: T.y + 25 }, '#d8fbff', 1.1);
164:       ctx.globalAlpha = 1;
165:       // shoreline foam
166:       const foam = (dir) => {
167:         const n = neighbor(world, x, y, dir);
168:         if (!n || n.terrain === 'water') return;
169:         if (dir === 'n') line(ctx, T, R, 'rgba(240,255,255,.6)', 2.2);
170:         if (dir === 'e') line(ctx, R, B, 'rgba(240,255,255,.55)', 2);
171:         if (dir === 's') line(ctx, B, L, 'rgba(240,255,255,.55)', 1.8);
172:         if (dir === 'w') line(ctx, L, T, 'rgba(240,255,255,.6)', 2);
173:       };
174:       foam('n'); foam('e'); foam('s'); foam('w');
175:       return;
176:     }
177:     let base;
178:     if (tile.terrain === 'sand') base = SAND[Math.floor(h * SAND.length)];
179:     else base = GRASS[Math.floor(h * GRASS.length)];
180:     poly(ctx, [T, R, B, L], base);
181:     if (tile.terrain === 'grass') {
182:       ctx.strokeStyle = 'rgba(45,100,40,.055)'; ctx.lineWidth = .8;
183:       ctx.stroke();
184:       if (h > .32) {
185:         const gx = T.x + 10 + hash(x + 3, y) * 30;
186:         const gy = T.y + 9 + hash(x, y + 5) * 12;
187:         ctx.globalAlpha = .35;
188:         line(ctx, { x: gx, y: gy }, { x: gx + 1.5, y: gy - 3.4 }, '#4d8a3e', 1);
189:         line(ctx, { x: gx + 1, y: gy }, { x: gx + 4, y: gy - 2.8 }, '#4d8a3e', .9);
190:         line(ctx, { x: gx + 1, y: gy }, { x: gx - 1.7, y: gy - 2.6 }, '#5a9648', .9);
191:         if (h > .75) {
192:           ctx.fillStyle = h > .9 ? '#f7d85e' : '#f2fdf8';
193:           ctx.beginPath(); ctx.arc(gx + 6, gy - 3, 1.15, 0, 7); ctx.fill();
194:         }
195:         ctx.globalAlpha = 1;
196:       }
197:     } else if (tile.terrain === 'sand') {
198:       ctx.globalAlpha = .28;
199:       ctx.fillStyle = '#b99f66';
200:       for (let i = 0; i < 2; i++) {
201:         const sx = T.x + 12 + hash(x + i, y + 1) * 30;
202:         const sy = T.y + 8 + hash(x + 2, y + i) * 12;
203:         ctx.beginPath(); ctx.arc(sx, sy, .9, 0, 7); ctx.fill();
204:       }
205:       ctx.globalAlpha = 1;
206:     }
207:   }
208:   // Directions match the four visible diamond edges: n=T-R (+x), e=R-B (+y),
209:   // s=B-L (-x), and w=L-T (-y).
210:   function neighbor(world, x, y, dir) {
211:     const dx = dir === 'n' ? 1 : dir === 's' ? -1 : 0;
212:     const dy = dir === 'e' ? 1 : dir === 'w' ? -1 : 0;
213:     const nx = x + dx, ny = y + dy;
214:     if (nx < 0 || ny < 0 || nx >= world.gridSize || ny >= world.gridSize) return null;
215:     return world.grid[ny * world.gridSize + nx];
216:   }
217:   function isRoad(world, x, y) {
218:     if (x < 0 || y < 0 || x >= world.gridSize || y >= world.gridSize) return false;
219:     return world.grid[y * world.gridSize + x].road;
220:   }
221:   function drawRoad(ctx, world, x, y, tile) {
222:     const T = iso(x, y), R = iso(x + 1, y), B = iso(x + 1, y + 1), L = iso(x, y + 1);
223:     const col = '#505a62';
224:     // Keep the road surface clean; vehicles define the lanes as they pass.
225:     poly(ctx, [T, R, B, L], col);
226:   }
227: 
228:   // ---------- building primitives ----------
229:   function boxGeo(x, y, w, h, inset) {
230:     const i = inset == null ? .07 : inset;
231:     return {
232:       T: iso(x + i, y + i), R: iso(x + w - i, y + i), B: iso(x + w - i, y + h - i), L: iso(x + i, y + h - i)
233:     };
234:   }
235:   function drawBox(ctx, x, y, w, h, height, opt) {
236:     const o = opt || {};
237:     const g = boxGeo(x, y, w, h, o.inset);
238:     const wall = o.wall || '#f0e3c8';
239:     const left = o.left || shade(wall, .84);
240:     const right = o.right || shade(wall, .67);
241:     const top = o.top || wall;
242:     const up = (p, dy) => ({ x: p.x, y: p.y - (dy || height) });
243:     poly(ctx, [g.L, g.B, up(g.B), up(g.L)], left);
244:     poly(ctx, [g.B, g.R, up(g.R), up(g.B)], right);
245:     poly(ctx, [up(g.T), up(g.R), up(g.B), up(g.L)], top);
246:     if (o.outline !== false) {
247:       ctx.strokeStyle = o.outlineColor || 'rgba(20,42,32,.16)';
248:       ctx.lineWidth = .8;
249:       poly(ctx, [g.L, g.B, up(g.B), up(g.L)], null, ctx.strokeStyle, .8);
250:       poly(ctx, [g.B, g.R, up(g.R), up(g.B)], null, ctx.strokeStyle, .8);
251:     }
252:     return { g, height, up, top: top };
253:   }
254:   function drawPitchedRoof(ctx, g, height, rise, color, opt) {
255:     const o = opt || {};
256:     const y = height;
257:     const T = { x: g.T.x, y: g.T.y - y }, R = { x: g.R.x, y: g.R.y - y }, B = { x: g.B.x, y: g.B.y - y }, L = { x: g.L.x, y: g.L.y - y };
258:     const cx = (T.x + B.x) / 2, cy = (T.y + B.y) / 2;
259:     const apex = { x: cx, y: cy - rise };
260:     const over = o.over || 0;
261:     if (over) {
262:       const dirs = [[T, R], [R, B], [B, L], [L, T]];
263:       for (const [a, b] of dirs) {
264:         const na = { x: a.x + (a.x - cx) * .06, y: a.y + (a.y - cy) * .06 };
265:         const nb = { x: b.x + (b.x - cx) * .06, y: b.y + (b.y - cy) * .06 };
266:         poly(ctx, [a, b, nb, na], shade(color, .7));
267:       }
268:     }
269:     poly(ctx, [L, B, apex], shade(color, .86));
270:     poly(ctx, [B, R, apex], shade(color, .66));
271:     if (o.ridge !== false) {
272:       line(ctx, apex, { x: lerp(L.x, B.x, .5), y: lerp(L.y, B.y, .5) - rise * .0 }, shade(color, .55), 1.2);
273:     }
274:     if (o.tiles) {
275:       ctx.globalAlpha = .18;
276:       for (let i = 1; i <= 3; i++) {
277:         const t = i / 4;
278:         const a = { x: lerp(L.x, B.x, t / 2), y: lerp(L.y, B.y, t / 2) };
279:         const b = { x: lerp(apex.x, B.x, t * .8), y: lerp(apex.y, B.y, t * .8) };
280:         line(ctx, { x: lerp(L.x, B.x, 1 - t), y: lerp(L.y, B.y, 1 - t) }, { x: lerp(apex.x, L.x, .5), y: lerp(apex.y, L.y, .5) }, shade(color, .5), .8);
281:       }
282:       ctx.globalAlpha = 1;
283:     }
284:   }
285:   function drawWindows(ctx, faceA, faceB, height, rows, cols, opt) {
286:     const o = opt || {};
287:     const top = o.top || 6, bottom = o.bottom || 7;
288:     const usable = height - top - bottom;
289:     if (usable < 6) return;
290:     const winH = Math.min(o.winH || 6, usable / rows * .5);
291:     const winW = o.winW || 4.6;
292:     const col = NIGHT > .28 ? '#ffd98a' : (o.color || '#bfe6f5');
293:     const frame = o.frame || 'rgba(255,255,255,.28)';
294:     const stepX = (faceB.x - faceA.x) / cols;
295:     const stepY = (faceB.y - faceA.y) / cols;
296:     for (let r = 0; r < rows; r++) {
297:       const wy = height - top - (usable / rows) * (r + .5);
298:       for (let c = 0; c < cols; c++) {
299:         const cx = faceA.x + stepX * (c + .5);
300:         const cy = faceA.y + stepY * (c + .5) - wy;
301:         const ex = (stepX / Math.abs(stepX || 1)) * winW;
302:         ctx.beginPath();
303:         ctx.moveTo(cx - ex / 2, cy);
304:         ctx.lineTo(cx + ex / 2, cy);
305:         ctx.lineTo(cx + ex / 2, cy + winH);
306:         ctx.lineTo(cx - ex / 2, cy + winH);
307:         ctx.closePath();
308:         ctx.fillStyle = col; ctx.fill();
309:         if (o.frame !== false) {
310:           ctx.strokeStyle = frame; ctx.lineWidth = .5; ctx.stroke();
311:         }
312:         if (NIGHT > .28) {
313:           ctx.globalAlpha = .18;
314:           ctx.fillStyle = '#ffe7a8';
315:           ctx.fillRect(cx - ex / 2 - 1, cy - 1, Math.abs(ex) + 2, winH + 2);
316:           ctx.globalAlpha = 1;
317:         }
318:       }
319:     }
320:   }
321:   function drawDoor(ctx, g, height, color, opt) {
322:     const o = opt || {};
323:     const frac = o.frac == null ? .5 : o.frac;
324:     const dx = lerp(g.L.x, g.B.x, frac), dy = lerp(g.L.y, g.B.y, frac);
325:     const w = o.w || 5, h = o.h || 10;
326:     poly(ctx, [
327:       { x: dx - w / 2, y: dy - h }, { x: dx + w / 2, y: dy - h },
328:       { x: dx + w / 2, y: dy }, { x: dx - w / 2, y: dy }
329:     ], color || '#7a5a3a');
330:     ctx.fillStyle = 'rgba(255,255,255,.18)';
331:     ctx.fillRect(dx + w / 2 - 1.6, dy - h / 2, 1, 1);
332:   }
333:   function drawAwning(ctx, g, height, colorA, colorB, y) {
334:     const baseY = y == null ? height - 13 : y;
335:     const segments = 6;
336:     for (let i = 0; i < segments; i++) {
337:       const t0 = i / segments, t1 = (i + 1) / segments;
338:       const a0 = { x: lerp(g.L.x, g.B.x, t0), y: lerp(g.L.y, g.B.y, t0) - baseY };
339:       const a1 = { x: lerp(g.L.x, g.B.x, t1), y: lerp(g.L.y, g.B.y, t1) - baseY };
340:       const b0 = { x: a0.x + 2, y: a0.y + 4 }, b1 = { x: a1.x + 2, y: a1.y + 4 };
341:       poly(ctx, [a0, a1, b1, b0], i % 2 ? colorB : colorA);
342:     }
343:   }
344:   function addVariantColors(b, palettes) {
345:     const idx = Math.abs(Math.floor(hash(b.x * 7 + b.uid * .17, b.y * 11 + b.level * 3) * palettes.length)) % palettes.length;
346:     return palettes[idx];
347:   }
