349:   // object dispatch & main render (art functions below)
350:   function defOf(b) { return DEFS[b.defId]; }
351:   function artFor(def, level) {
352:     if (def.kind === 'zone-r') return level > 0 ? 'house' : 'lot_r';
353:     if (def.kind === 'zone-c') return level > 0 ? 'shop' : 'lot_c';
354:     if (def.kind === 'zone-i') return level > 0 ? 'factory' : 'lot_i';
355:     return def.art;
356:   }
357:   function artHeight(def, level) {
358:     const lv = level || 1;
359:     if (def.kind === 'zone-r') return [0, 52, 64, 80, 100][Math.min(lv, 4)];
360:     if (def.kind === 'zone-c') return [0, 48, 64, 84][Math.min(lv, 3)];
361:     if (def.kind === 'zone-i') return [0, 68, 80, 92][Math.min(lv, 3)];
362:     const map = {
363:       powerplant: 112, watertower: 78, solar: 46, police: 54, fire: 60, school: 86, hospital: 96,
364:       smallpark: 54, park: 74, plaza: 64, fountain: 58, ferris: 126, stadium: 100, monument: 96,
365:       tree: 58, flowers: 44, streetlamp: 54, rock: 36, lot_r: 34, lot_c: 34, lot_i: 34
366:     };
367:     return map[def.art] || 60;
368:   }
369:   function drawObject(ctx, b, time) {
370:     const def = defOf(b);
371:     if (!def) return;
372:     if (def.kind === 'road' || b.defId === 'road') return;
373:     // shadow
374:     const sh = diamondPoints(b.x + (b.w - 1) * .5, b.y + (b.h - 1) * .5, b.w + .16, b.h + .16, .02);
375:     ctx.save();
376:     ctx.translate(2.5, 3.5);
377:     poly(ctx, sh, 'rgba(20,55,35,.16)');
378:     ctx.restore();
379:     const art = b.art || artFor(def, b.level);
380:     switch (art) {
381:       case 'lot_r': return drawLot(ctx, b, def, '#5ab86c', 'R', time);
382:       case 'lot_c': return drawLot(ctx, b, def, '#4a9bda', 'C', time);
383:       case 'lot_i': return drawLot(ctx, b, def, '#dcaa46', 'I', time);
384:       case 'house': return drawHouse(ctx, b, def, time);
385:       case 'shop': return drawShop(ctx, b, def, time);
386:       case 'factory': return drawFactory(ctx, b, def, time);
387:       case 'powerplant': return drawPowerPlant(ctx, b, time);
388:       case 'watertower': return drawWaterTower(ctx, b, time);
389:       case 'solar': return drawSolar(ctx, b, time);
390:       case 'police': return drawPolice(ctx, b, time);
391:       case 'fire': return drawFire(ctx, b, time);
392:       case 'school': return drawSchool(ctx, b, time);
393:       case 'hospital': return drawHospital(ctx, b, time);
394:       case 'smallpark': return drawSmallPark(ctx, b, time);
395:       case 'park': return drawPark(ctx, b, time);
396:       case 'plaza': return drawPlaza(ctx, b, time);
397:       case 'fountain': return drawFountain(ctx, b, time);
398:       case 'ferris': return drawFerris(ctx, b, time);
399:       case 'stadium': return drawStadium(ctx, b, time);
400:       case 'monument': return drawMonument(ctx, b, time);
401:       case 'tree': return drawTree(ctx, b, def, time);
402:       case 'flowers': return drawFlowers(ctx, b, time);
403:       case 'streetlamp': return drawStreetLamp(ctx, b, time);
404:       case 'rock': return drawRock(ctx, b, time);
405:       default: return;
406:     }
407:   }
408: 
409:   function drawWorld(ctx, world, cam, viewW, viewH, zoom, time, opts) {
410:     opts = opts || {};
411:     NIGHT = opts.night || 0;
412:     TIME = time;
413:     ctx.setTransform(1, 0, 0, 1, 0, 0);
414:     ctx.clearRect(0, 0, viewW * (opts.dpr || 1), viewH * (opts.dpr || 1));
415:     const dpr = opts.dpr || 1;
416:     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
417:     drawBackground(ctx, viewW, viewH, time);
418:     ctx.setTransform(dpr * zoom, 0, 0, dpr * zoom, dpr * (viewW / 2 - cam.x * zoom), dpr * (viewH / 2 - cam.y * zoom));
419:     drawPlate(ctx, world.gridSize);
420:     const left = cam.x - viewW / (2 * zoom) - 90;
421:     const right = cam.x + viewW / (2 * zoom) + 90;
422:     const top = cam.y - viewH / (2 * zoom) - 200;
423:     const bottom = cam.y + viewH / (2 * zoom) + 130;
424:     for (let y = 0; y < world.gridSize; y++) {
425:       for (let x = 0; x < world.gridSize; x++) {
426:         const t = world.grid[y * world.gridSize + x];
427:         if (!t) continue;
428:         const s = iso(x, y);
429:         if (s.x < left - 90 || s.x > right + 90 || s.y < top - 80 || s.y > bottom + 80) continue;
430:         drawTerrain(ctx, world, x, y, t, time);
431:         if (t.road) drawRoad(ctx, world, x, y, t);
432:       }
433:     }
434:     if (opts.placements && opts.placements.length) {
435:       drawPlacementCandidates(ctx, opts.placements, { left, right, top, bottom }, time);
436:     }
437:     const objs = [];
438:     for (const b of world.buildings) {
439:       const s = iso(b.x, b.y);
440:       if (s.x < left - 260 || s.x > right + 260 || s.y < top - 120 || s.y > bottom + 260) continue;
441:       objs.push({ d: b.x + b.y + (b.w + b.h - 2) * .34, b });
442:     }
443:     if (world.cars) {
444:       for (const c of world.cars) {
445:         if (c.x < left / 32 - 20 || c.y < top / 16 - 20) { /* rough */ }
446:         objs.push({ d: c.x + c.y, car: c });
447:       }
448:     }
449:     objs.sort((a, b) => a.d - b.d);
450:     for (const o of objs) {
451:       if (o.b) drawObject(ctx, o.b, time);
452:       else drawCar(ctx, o.car, time);
453:     }
454:     if (opts.selected) {
455:       const b = opts.selected;
456:       const pts = diamondPoints(b.x, b.y, b.w, b.h, .02);
457:       ctx.save();
458:       ctx.setLineDash([6, 4]);
459:       poly(ctx, pts, 'rgba(255,255,255,.05)', 'rgba(255,255,255,.9)', 2.2);
460:       ctx.setLineDash([]);
461:       ctx.restore();
462:       if (DEFS[b.defId] && DEFS[b.defId].radius) drawZoneRadius(ctx, b, 'rgba(46,194,126,.55)');
463:     }
464:     if (opts.ghost) drawGhost(ctx, opts.ghost, time);
465:     // night overlay (screen space)
466:     if (NIGHT > .02) {
467:       ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
468:       ctx.fillStyle = `rgba(14,26,62,${NIGHT * .3})`;
469:       ctx.fillRect(0, 0, viewW, viewH);
470:       if (opts.dusk) {
471:         ctx.fillStyle = `rgba(255,127,58,${opts.dusk * .12})`;
472:         ctx.fillRect(0, 0, viewW, viewH);
473:       }
474:     }
475:   }
