652:   function flatRoof(g, height, color, lipColor) {
653:     const T = { x: g.T.x, y: g.T.y - height }, R = { x: g.R.x, y: g.R.y - height }, B = { x: g.B.x, y: g.B.y - height }, L = { x: g.L.x, y: g.L.y - height };
654:     poly(ctx, [L, B, B, L], null);
655:     poly(ctx, [T, R, B, L].map(p => ({ x: lerp(p.x, (T.x + B.x) / 2, .08), y: lerp(p.y, (T.y + B.y) / 2, .08) })), color || '#d9d1c1');
656:     return { T, R, B, L };
657:   }
658:   function roofLip(ctx, g, height, color) {
659:     const T = { x: g.T.x, y: g.T.y - height }, R = { x: g.R.x, y: g.R.y - height }, B = { x: g.B.x, y: g.B.y - height }, L = { x: g.L.x, y: g.L.y - height };
660:     const cx = (T.x + B.x) / 2, cy = (T.y + B.y) / 2;
661:     const inset = p => ({ x: lerp(p.x, cx, .07), y: lerp(p.y, cy, .07) });
662:     const iT = inset(T), iR = inset(R), iB = inset(B), iL = inset(L);
663:     poly(ctx, [T, R, iR, iT], color); poly(ctx, [R, B, iB, iR], shade(color, .82));
664:     poly(ctx, [B, L, iL, iB], shade(color, .75)); poly(ctx, [L, T, iT, iL], shade(color, .92));
665:   }
666:   function cylinder(ctx, cx, baseY, rx, h, color) {
667:     const topY = baseY - h;
668:     const grd = ctx.createLinearGradient(cx - rx, 0, cx + rx, 0);
669:     grd.addColorStop(0, shade(color, .78));
670:     grd.addColorStop(.45, light(color, .12));
671:     grd.addColorStop(1, shade(color, .66));
672:     ctx.fillStyle = grd;
673:     ctx.beginPath(); ctx.moveTo(cx - rx, topY); ctx.lineTo(cx - rx, baseY); ctx.ellipse(cx, baseY, rx, rx * .42, 0, Math.PI, 0, true); ctx.lineTo(cx + rx, topY); ctx.closePath(); ctx.fill();
674:     ellipse(ctx, cx, topY, rx, rx * .42, light(color, .17), shade(color, .58), .7);
675:   }
676:   function smoke(ctx, cx, cy, time, scale) {
677:     const sc = scale || 1;
678:     for (let i = 0; i < 4; i++) {
679:       const t = (time * .19 + i * .25) % 1;
680:       const r = (4 + t * 12) * sc;
681:       ctx.globalAlpha = (1 - t) * .3;
682:       ctx.fillStyle = i % 2 ? '#e9f0ef' : '#d8e0df';
683:       ctx.beginPath(); ctx.arc(cx + Math.sin(time * .5 + i * 2.1) * 5 * sc, cy - t * 46 * sc, r, 0, 7); ctx.fill();
684:     }
685:     ctx.globalAlpha = 1;
686:   }
